    private void mni_estadisticasActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_mni_estadisticasActionPerformed
        VentanaEstadistica ventEsta = new VentanaEstadistica();
        ventEsta.setLocationRelativeTo(null);//muestra la ventana centrada en pantalla
        ventEsta.setTitle("Ventana Estadisticas");//aquí escribo el título de la ventana
        ventEsta.setResizable(false);//se evita que el usuario pueda cambiar el tamaño de la ventana
        ventEsta.setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);//evita que puedan cerrar la ventana con la X
        ventEsta.setVisible(true);//muestra la ventan
    }//GEN-LAST:event_mni_estadisticasActionPerformed

    private void mni_salir1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_mni_salir1ActionPerformed
        int opcion = JOptionPane.showConfirmDialog(null,"¿Seguro que desea salir?");
        if( opcion == JOptionPane.YES_OPTION){
            dispose();}
    }//GEN-LAST:event_mni_salir1ActionPerformed


